const bin = msg.topic.split("/")[2];
const d = msg.payload;

const ok = (v, lo, hi) =>
    typeof v === "number" && v >= lo && v <= hi;

const errors = [];

if (!ok(d.d, 0, 150)) errors.push("d");
if (d.h !== 120) errors.push("h");
if (!Number.isInteger(d.ts)) errors.push("ts");

if (errors.length > 0) {
    const n = (context.get("rejected") || 0) + 1;
    context.set("rejected", n);

    node.status({
        fill: "red",
        shape: "dot",
        text: `відхилено: ${n}`
    });

    msg.payload = {
        bin: bin,
        errors: errors,
        raw: d
    };

    return [null, msg];
}

msg.bin = bin;
msg.ts = d.ts;

msg.payload = {
    d: d.d,
    h: d.h
};

return [msg, null];

const ALPHA = 0.2;
const ON = 80.0;
const OFF = 30.0;

// Вікно для оцінки тренду — 10 хвилин
const WINDOW_MS = 30 * 60 * 1000;
const MIN_WINDOW_MS = 28 * 60 * 1000;

// Різке падіння F більше ніж на 20 п.п.
// вважаємо спорожненням контейнера
const COLLECTION_DROP = 20.0;

const d = msg.payload.d;
const H = msg.payload.h;
const fill = (H - d) / H * 100;

const key = "st_" + msg.bin;

const st = context.get(key) || {
    ema: null,
    alarm: 0,
    history: [],
    prevFill: null
};

// Виявлення спорожнення
const collected =
    st.prevFill !== null &&
    (st.prevFill - fill) >= COLLECTION_DROP;

if (collected) {
    // Після спорожнення старий тренд більше не має сенсу
    st.ema = fill;
    st.history = [];
} else {
    // EMA-згладжування
    st.ema = st.ema === null
        ? fill
        : ALPHA * fill + (1 - ALPHA) * st.ema;
}

st.prevFill = fill;

// Додаємо згладжене значення до історії
st.history.push({
    ts: msg.ts,
    ema: st.ema
});

// Зберігаємо лише останні 30 хвилин
const cutoff = msg.ts - WINDOW_MS;
st.history = st.history.filter(p => p.ts >= cutoff);

let rate = null;
let t100 = null;

// Швидкість r оцінюємо нахилом лінійної регресії
// за значеннями F_ema в часовому вікні
if (st.history.length >= 2) {

    const span =
        st.history[st.history.length - 1].ts -
        st.history[0].ts;

    if (span >= MIN_WINDOW_MS) {

        const t0 = st.history[0].ts;

        let sumX = 0;
        let sumY = 0;
        let sumXY = 0;
        let sumXX = 0;

        const n = st.history.length;

        for (const p of st.history) {
            // час у годинах від початку вікна
            const x = (p.ts - t0) / 3600000;
            const y = p.ema;

            sumX += x;
            sumY += y;
            sumXY += x * y;
            sumXX += x * x;
        }

        const denominator =
            n * sumXX - sumX * sumX;

        if (denominator !== 0) {
            rate =
                (n * sumXY - sumX * sumY) /
                denominator;
        }
    }
}

// t100 має сенс лише при додатній швидкості
if (rate !== null && rate > 0) {
    t100 = (100 - st.ema) / rate;
}

// Тривога з гістерезисом
const before = st.alarm;

if (st.alarm === 0 && st.ema >= ON) {
    st.alarm = 1;
}

if (st.alarm === 1 && st.ema <= OFF) {
    st.alarm = 0;
}

context.set(key, st);

msg.payload = {
    d: Math.round(d * 10) / 10,
    h: H,
    fill: Math.round(fill * 10) / 10,
    fill_ema: Math.round(st.ema * 10) / 10,
    rate: rate === null
        ? null
        : Math.round(rate * 10) / 10,
    t100: t100 === null
        ? null
        : Math.round(t100 * 10) / 10,
    alarm: st.alarm
};

let alarmMsg = null;

if (st.alarm !== before) {
    alarmMsg = {
        topic: `kharkiv/waste/${msg.bin}/alarm`,
        payload: JSON.stringify({
            ts: msg.ts,
            alarm: st.alarm,
            fill_ema: msg.payload.fill_ema
        })
    };
}

return [msg, alarmMsg];

const p = msg.payload;

msg.params = [
    msg.ts,
    msg.bin,
    p.d,
    p.h,
    p.fill,
    p.fill_ema,
    p.rate,
    p.t100,
    p.alarm,
    Date.now() - msg.ts
];

// Тимчасова перевірка
node.warn(msg.params);

return msg;

const bin = msg.topic.split("/")[2];
const online = msg.payload === "online" ? 1 : 0;

msg.params = [bin, online];

return msg;

